FTC.cost.source:
def cost (c : I → S → ℝ) (Q : Finset I) (s : S) : ℝ :=
  ∑ i ∈ Q, c i s

/-- The multiplicative coreset condition, including reference costs equal to zero. -/

FTC.cost_congr.source:
theorem cost_congr {c d : I → S → ℝ} {Q : Finset I}
    (h : ∀ i ∈ Q, ∀ s, c i s = d i s) (s : S) : cost c Q s = cost d Q s :=
  Finset.sum_congr rfl fun i hi => h i hi s

FTC.Counterexample.firstDistance.source:
def firstDistance {n : ℕ} (i : Fin n) : ℝ :=
  if i.val = 0 then 1 / 2 else 3 / 2

/-- Unit-simplex distance between original points. -/

FTC.Counterexample.exceptional.source:
def exceptional {n : ℕ} : Vertex n → Finset (Fin n)
  | .inl i => {i}
  | .inr false => Finset.univ.filter (fun i => i.val = 0)
  | .inr true => ∅

FTC.Counterexample.simplexQuery.source:
def simplexQuery {n : ℕ} (j l : Fin n) (hjl : j ≠ l) : Query n :=
  pairQuery (p j) (p l) (by simpa using hjl)

/-- The reference clustering `{a,p_j}`. -/

FTC.Executable.matrixDecodeCounted.source:
def matrixDecodeCounted (c : I → S → ℚ) (queries : Finset S)
    (f : ℕ) (U : Finset I) : WorkResult I :=
  runCounted (fun Q i => rationalSensitivity c queries Q i) f U

FTC.Executable.chargedMatrixWork.source:
def chargedMatrixWork (c : I → S → ℚ) (queries : Finset S) (f : ℕ) (U : Finset I) : ℕ :=
  let work := matrixDecodeCounted c queries f U
  work.scoreCalls * (queries.card * (2 * U.card + 3)) + work.comparisons

FTC.Executable.stepCounted.source:
def stepCounted (score : Finset I → I → ℚ) (Q : Finset I) : WorkResult I :=
  let evaluated := evaluateScores (score Q) (Q.sort (· ≤ ·))
  let scanned := maximumCounted evaluated.1
  match scanned.1 with
  | none => ⟨Q, evaluated.2, scanned.2, 0⟩
  | some p => ⟨Q.erase p.1, evaluated.2, scanned.2, 1⟩

FTC.Executable.constrainedFiniteSolver.source:
def constrainedFiniteSolver (c : I → S → ℚ) (U : Finset I) (candidates : List S)
    (admissible : S → Prop) [DecidablePred admissible] : Option S :=
  exactFiniteSolver c U (candidates.filter fun s => decide (admissible s))

FTC.Executable.constrainedFiniteSolverCo.source:
def constrainedFiniteSolverCounted (c : I → S → ℚ) (U : Finset I) (candidates : List S)
    (admissible : S → Prop) [DecidablePred admissible] : Option S × ℕ :=
  exactFiniteSolverCounted c U (candidates.filter fun s => decide (admissible s))

FTC.Executable.rationalKmeansLoss.source:
def rationalKmeansLoss (d : RationalMetric X) (entries : I → RationalEntry X)
    (i : I) (C : Finset X) : ℚ :=
  (entries i).weight * rationalPointLoss d (entries i).point C

FTC.Executable.rationalCost.source:
def rationalCost (c : I → S → ℚ) (U : Finset I) (s : S) : ℚ :=
  ∑ i ∈ U, c i s

/-- The same matrix interpreted as a real nonnegative pointwise objective. -/

FTC.Executable.rationalRatioCounted.source:
def rationalRatioCounted (c : I → S → ℚ) (U : Finset I) (i : I) (s : S) : ℚ × ℕ :=
  let denominator := rationalCostCounted c U s
  (c i s / denominator.1, denominator.2 + 2)

FTC.Executable.rationalSensitivityCounte.source:
def rationalSensitivityCounted (c : I → S → ℚ) (queries : Finset S)
    (U : Finset I) (i : I) : ℚ × ℕ :=
  if i ∈ U then queries.fold maxWithWork (0, 0) (rationalRatioCounted c U i) else (0, 0)

FTC.Hardness.Encoding.exactFullSensitivi.source:
def exactFullSensitivity (x : FullData) (h : ValidFull x) : ℚ :=
  exactRationalKmeansSensitivity h.metric (fullRationalEntries x)
    h.centers_pos (fullClients x) none

FTC.Hardness.Encoding.expandedMatrix.source:
def expandedMatrix (x : TargetData) : MatrixData :=
  ((0, 0) :: x.1.1.map (fun _ => (x.2.1, 0))) ::
    x.1.1.map (fun row => (x.2.1, 0) :: row)

FTC.Hardness.Encoding.firstRowCode.source:
def firstRowCode : Code TargetTy (.list RatTy) :=
  .comp (.pair (.const (0, 0))
    (.comp (.pair targetRadiusCode baseMatrixCode) (.mapWith .fst))) .cons

FTC.Hardness.Encoding.weightsCode.source:
def weightsCode : Code TargetTy (.list RatTy) :=
  .comp (.pair (.const (1, 0))
    (.comp (.pair targetWeightCode baseMatrixCode) (.mapWith .fst))) .cons

FTC.Hardness.Encoding.materializeCode.source:
def materializeCode : Code TargetTy FullTy :=
  .pair (.comp baseMatrixCode .length)
    (.pair expandedMatrixCode (.pair flagsCode (.pair weightsCode targetCentersCode)))

FTC.Hardness.amplification_pos.source:
theorem amplification_pos {c : ℕ} (hc : 0 < c) {D B : ℝ}
    (hD : 0 < D) (hB : 0 < B) : 0 < amplification c D B := by
  unfold amplification
  positivity

variable {X : Type*} [DecidableEq X] [Fintype X] [MetricSpace X] {k : ℕ}

/-- The radius cancels out under the chosen amplification. -/

FTC.Hardness.approximationDecider_polyno.source:
theorem approximationDecider_polynomial (t : ℚ) {algorithm : Code TargetTy RatTy}
    (h : algorithm.IsPoly) : (approximationDecider t algorithm).IsPoly :=
  h.comp (thresholdCode_polynomial _)

FTC.Hardness.gadgetEntries.source:
def gadgetEntries (L : ℝ) (hL : 0 ≤ L) : Option X → Entry (Option X)
  | none => ⟨none, 1, by norm_num⟩
  | some x => ⟨some x, L, hL⟩

FTC.Hardness.Encoding.matrixDistance.source:
def matrixDistance (m : MatrixData) (x y : Fin m.length) : ℚ :=
  rational ((m.getD x []).getD y (0, 0))

/-- The finite metric and feasibility promises, stated entirely over rationals. -/

FTC.LowerBound.supportedCost.source:
noncomputable def supportedCost {I : Type*} [DecidableEq I] {k : ℕ}
    (Q : Finset I) (loc : I → Fin k) (a : I → ℝ) (S : EuclideanQuery k) : ℝ :=
  ∑ j ∈ Q, a j * sqDistToCenters (basisPoint (loc j)) S

FTC.Probability.badHistogram.source:
def badHistogram (p : PMF J) (ε : ℝ) (m : ℕ) : Set (Fin m → J) :=
  {sample | ∃ x, ε * ((m : ℝ) * mass p x) ≤
    |histogram sample x - (m : ℝ) * mass p x|}

/-- The reciprocal-mass sum in the explicit finite-input fallback bound. -/

FTC.Probability.histogram.source:
def histogram {m : ℕ} (sample : Fin m → J) (x : J) : ℝ :=
  ∑ i, hit x (sample i)

/-- An inverse-probability weighted sample, with individual `Fin m` indices. -/

FTC.SucceedsWithProbabilityAtLeast.source:
def SucceedsWithProbabilityAtLeast (μ : Measure Ω) (p : ℝ≥0∞)
    (predicate : Ω → Prop) : Prop :=
  ∃ E : Set Ω, MeasurableSet E ∧ p ≤ μ E ∧ ∀ ω ∈ E, predicate ω

FTC.totalScore.source:
def totalScore (score : J → ℝ) (P : Finset J) : ℝ :=
  ∑ x ∈ P, score x

/-- The total sensitivity `T` appearing in Theorem 3.1. -/

FTC.totalScore_nonneg.source:
theorem totalScore_nonneg {score : J → ℝ} {P : Finset J}
    (hscore : ∀ x ∈ P, 0 ≤ score x) : 0 ≤ totalScore score P :=
  Finset.sum_nonneg hscore

FTC.sensitivityRatios.source:
def sensitivityRatios (c : I → S → ℝ) (Q : Finset I) (i : I) : Set ℝ :=
  insert 0 (Set.range fun s : S => c i s / cost c Q s)

/-- Exact sensitivity of an entry; an inactive index has sensitivity zero. -/

FTC.sensitivity.source:
noncomputable def sensitivity (c : I → S → ℝ) (Q : Finset I) (i : I) : ℝ :=
  if i ∈ Q then sSup (sensitivityRatios c Q i) else 0

variable {c : I → S → ℝ}
